package com.example.insightku.navigation

import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Analytics
import androidx.compose.material.icons.filled.Dashboard
import androidx.compose.material.icons.filled.AccountBalance
import androidx.compose.material.icons.filled.Settings
import androidx.compose.ui.graphics.vector.ImageVector

sealed class Screen(
    val route: String,
    val title: String,
    val icon: ImageVector? = null
) {
    // Auth Screens
    object Login : Screen(
        route = "login",
        title = "Login"
    )

    object SignUp : Screen(
        route = "signup", 
        title = "Sign Up"
    )

    object ForgotPassword : Screen(
        route = "forgot_password",
        title = "Forgot Password"
    )

    // Main App Screens  
    object Dashboard : Screen(
        route = "dashboard",
        title = "Dashboard",
        icon = Icons.Default.Dashboard
    )

    object Analytics : Screen(
        route = "analytics",
        title = "Analytics", 
        icon = Icons.Default.Analytics
    )

    object Budgeting : Screen(
        route = "budgeting",
        title = "Budgeting",
        icon = Icons.Default.AccountBalance
    )

    object Settings : Screen(
        route = "settings",
        title = "Settings",
        icon = Icons.Default.Settings
    )

    // Helper function to get bottom navigation items
    companion object {
        fun getBottomNavItems(): List<Screen> {
            return listOf(
                Dashboard,
                Analytics, 
                Budgeting,
                Settings
            )
        }

        fun getAuthScreens(): List<Screen> {
            return listOf(
                Login,
                SignUp,
                ForgotPassword
            )
        }
    }
}

// Bottom Navigation Item data class
data class BottomNavItem(
    val screen: Screen,
    val selectedIcon: ImageVector,
    val unselectedIcon: ImageVector,
    val hasNews: Boolean = false,
    val badgeCount: Int? = null
)

// Pre-defined bottom navigation items
val bottomNavItems = listOf(
    BottomNavItem(
        screen = Screen.Dashboard,
        selectedIcon = Icons.Default.Dashboard,
        unselectedIcon = Icons.Default.Dashboard
    ),
    BottomNavItem(
        screen = Screen.Analytics, 
        selectedIcon = Icons.Default.Analytics,
        unselectedIcon = Icons.Default.Analytics
    ),
    BottomNavItem(
        screen = Screen.Budgeting,
        selectedIcon = Icons.Default.AccountBalance,
        unselectedIcon = Icons.Default.AccountBalance
    ),
    BottomNavItem(
        screen = Screen.Settings,
        selectedIcon = Icons.Default.Settings,
        unselectedIcon = Icons.Default.Settings
    )
)

